import {
  Group,
  Mesh,
  PlaneGeometry,
  CylinderGeometry,
  SphereGeometry,
  Color,
  Box3,
  Vector3,
  Clock,
  DirectionalLight,
  PointLight,
  DoubleSide,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, mix, smoothstep, vec2, vec3, length } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'orrery-mechanism';

  const colors =
    config.intent?.visualSpec?.colors ?? config.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      gradientStops: [
        { at: 0, hex: '#0b0b10' },
        { at: 0.65, hex: '#101017' },
        { at: 1, hex: '#16161d' },
      ],
    };

  const disposables = [];

  // ---------------------------------------------------------------------
  // BACKDROP — engineered vertical gradient plane
  // ---------------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new Color(stops[0].hex);
  const c1 = new Color(stops[1].hex);
  const c2 = new Color(stops[2].hex);

  const vy = uv().y;
  const mixA = smoothstep(stops[0].at, stops[1].at, vy);
  const mixB = smoothstep(stops[1].at, stops[2].at, vy);
  const lowMix = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), mixA);
  const gradientColor = mix(lowMix, vec3(c2.r, c2.g, c2.b), mixB);

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = gradientColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------------
  // CONTACT SHADOW — soft radial ellipse
  // ---------------------------------------------------------------------
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
  });
  const centered = uv().sub(vec2(0.5, 0.5));
  const ellipseDist = length(vec2(centered.x, centered.y.mul(2.166)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(0.5, 0.05, ellipseDist).mul(0.5);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -1.2, -0.15);
  root.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------------
  // ARBOR SHAFTS
  // ---------------------------------------------------------------------
  const shaftMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink ?? '#16161d'),
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.15,
    clearcoatRoughness: 0.35,
  });
  disposables.push(shaftMat);

  function makeShaft(x, y, z) {
    const geo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
    geo.rotateX(Math.PI / 2);
    const mesh = new Mesh(geo, shaftMat);
    mesh.position.set(x, y, z);
    disposables.push(geo);
    return mesh;
  }

  const primaryPivot = new Group();
  primaryPivot.position.set(0, 0, 0);
  primaryPivot.add(makeShaft(0, 0, 0));
  root.add(primaryPivot);

  const secondaryPivot = new Group();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  secondaryPivot.add(makeShaft(0, 0, 0));
  root.add(secondaryPivot);

  // ---------------------------------------------------------------------
  // JEWEL PIVOT — accent gem at primary hub
  // ---------------------------------------------------------------------
  const accentColor = new Color(colors.accent ?? '#ff2a38');
  const jewelGeo = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: accentColor,
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.08,
    metalness: 0.0,
    emissive: accentColor,
    emissiveIntensity: 1.8,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.1);
  primaryPivot.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  const jewelGlow = new PointLight(accentColor.getHex(), 0.6, 2.5);
  jewelGlow.position.set(0, 0, 0.4);
  root.add(jewelGlow);

  // ---------------------------------------------------------------------
  // NODE-LOCAL RIM LIGHT (accent-tinted, opposite key)
  // ---------------------------------------------------------------------
  const rimLight = new DirectionalLight(accentColor.getHex(), 0.7);
  rimLight.position.set(-2.2, 1.1, 2.8);
  root.add(rimLight);

  // ---------------------------------------------------------------------
  // GEAR MESHES (async GLB load, sync placeholders)
  // ---------------------------------------------------------------------
  const primaryGearGroup = new Group();
  primaryPivot.add(primaryGearGroup);

  const secondaryGearGroup = new Group();
  secondaryPivot.add(secondaryGearGroup);

  function applyMachinedSteel(objRoot) {
    objRoot.traverse((child) => {
      if (child.isMesh) {
        const mat = new MeshPhysicalNodeMaterial({
          color: new Color('#3a3a42'),
          roughness: 0.5,
          metalness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.3,
        });
        if ('anisotropy' in mat) mat.anisotropy = 0.7;
        child.material = mat;
        disposables.push(mat);
      }
    });
  }

  function normalize(objRoot, targetDiameter) {
    const box = new Box3().setFromObject(objRoot);
    const size = new Vector3();
    box.getSize(size);
    const maxDim = Math.max(size.x, size.y, size.z) || 1;
    const scaleFactor = targetDiameter / maxDim;
    objRoot.scale.setScalar(scaleFactor);
    const box2 = new Box3().setFromObject(objRoot);
    const center = new Vector3();
    box2.getCenter(center);
    objRoot.position.sub(center);
  }

  let gltfLoaded = false;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!gltf || !gltf.scene) return;
    gltfLoaded = true;

    const primaryScene = gltf.scene;
    normalize(primaryScene, 1.6);
    applyMachinedSteel(primaryScene);
    primaryGearGroup.add(primaryScene);

    const secondaryScene = primaryScene.clone(true);
    // re-normalize the clone independently to hit the 0.9 diameter target
    secondaryScene.scale.set(1, 1, 1);
    secondaryScene.position.set(0, 0, 0);
    normalize(secondaryScene, 0.9);
    applyMachinedSteel(secondaryScene);
    secondaryGearGroup.add(secondaryScene);
  }).catch(() => {
    // fail-quiet: mechanism reads as arbors + jewel only
  });

  // meshing rotation — phase-locked ratio 16:9
  const clock = new Clock();
  const primarySpeed = 0.08;
  const secondarySpeed = -0.142;
  function tick() {
    const dt = Math.min(clock.getDelta(), 0.1);
    primaryGearGroup.rotation.z += primarySpeed * dt;
    secondaryGearGroup.rotation.z += secondarySpeed * dt;
  }
  gsap.ticker.add(tick);

  // ---------------------------------------------------------------------
  // TEXT CONTENT
  // ---------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'The going train', role: 'headline' },
    { text: '34 COMPONENTS / HAND-FINISHED', role: 'caption' },
  ];

  const paper = colors.paper ?? '#e8ecf2';
  const textNodes = [];
  for (const item of items) {
    if (item.role === 'headline') {
      const headline = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: paper,
        align: 'center',
      });
      headline.position.set(0, -1.7, 0);
      root.add(headline);
      textNodes.push(headline);
    } else if (item.role === 'caption') {
      const caption = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: paper,
        align: 'center',
        letterSpacingPx: 1.44,
      });
      caption.position.set(0, -2.1, 0);
      root.add(caption);
      textNodes.push(caption);
    }
  }

  // ---------------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------------
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------------
  root.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    for (const handle of primitiveHandles) {
      handle.cleanup?.();
      handle.timeline?.kill?.();
    }
    for (const item of disposables) {
      item.dispose?.();
    }
    for (const node of textNodes) {
      node.geometry?.dispose?.();
      node.material?.dispose?.();
    }
    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
